// A credential-free fallback for later articles. The initial report is researched
// prose in report.json. This fallback labels its output as data + rule analysis.
function matchTopic(text) {
 if(/匯率|匯市|新台幣|台幣|人民幣|日圓/.test(text))return '匯率與資金';
 if(/通膨|PPI|CPI|物價/.test(text))return '通膨與利率';
 if(/IMF|全球景氣|亞洲經濟|全球經濟/.test(text))return '全球景氣';
 if(/GDP|經濟成長|經濟預測/.test(text))return '經濟成長';
 if(/公債|美債|殖利率|聯準會|Fed|升息|降息/.test(text))return '貨幣與貿易';
}
export function topicFor(title,body='') {return matchTopic(title)||matchTopic(body)||'貨幣與貿易';}
function metrics(text) {
 const patterns=[
  /(?:核心PPI|核心CPI|PPI|CPI|GDP)[^。；]{0,16}?(?:月增|年增|成長|上修至|下修至|為|達|至)[約率\s：:]*\d+(?:\.\d+)?[％%]/gi,
  /(?:經濟成長率|出口年增率|進口年增率|零售銷售|公債殖利率)[^。；]{0,18}?\d+(?:\.\d+)?[％%]/g,
  /(?:新台幣|台幣|美元兌日圓)[^。；]{0,14}?(?:觸及|收在|收報|貶至|升至|為|達|至)[約\s]*\d+(?:\.\d+)?元/g,
 ];
 const out=[];
 for(const regex of patterns)for(const m of text.matchAll(regex)) {
  // These are indicators and numerical facts, never full source paragraphs.
  const n=m[0].replace(/（[^）]*）/g,'').replace(/[「」]/g,'').trim();
  if(!out.includes(n))out.push(n);
 }
 return out.slice(0,6);
}
